package main

import (
	_ "embed"
	"strings"

	"github.com/rivo/tview"
)

// THIRD_PARTY_LICENSES.txt is generated by tools/licenses (go run
// ./tools/licenses -write); CI checks that it is up to date.
var (
	//go:embed LICENSE
	ownLicense string
	//go:embed THIRD_PARTY_LICENSES.txt
	thirdPartyLicenses string
)

// licensesText is tsnmp's own license followed by the third-party licenses
// (for -licenses and the Licenses page).
func licensesText() string {
	return "tsnmp\n=====\n\n" + strings.TrimSpace(ownLicense) +
		"\n\n\nThird-party software\n====================\n\n" + thirdPartyLicenses
}

// showLicenses opens the Licenses page on top of the help (l key there).
// The text is plain: license texts may contain "[", a tview color code.
func (a *App) showLicenses() {
	text := tview.NewTextView().SetWordWrap(true).SetText(licensesText())
	text.SetBorder(true).SetTitle(" Licenses (Esc: back, ↑ / ↓ / PgUp / PgDn: scroll) ")
	box := &centered{Box: tview.NewBox(), child: text, w: 84, h: 1 << 16}
	a.licensesReturnFocus = a.app.GetFocus()
	a.pages.AddPage("licenses", box, true, true)
	a.app.SetFocus(text)
}

func (a *App) closeLicenses() {
	a.pages.RemovePage("licenses")
	if a.licensesReturnFocus != nil {
		a.app.SetFocus(a.licensesReturnFocus)
	}
}
